using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using RoadGunner;using RoadGunner.Editor;
public static class LevelEditorSaveAsChecks{
 public static string Main(){var lines=new System.Collections.Generic.List<string>();void C(string n,bool ok){lines.Add((ok?"PASS ":"FAIL ")+n);if(!ok)throw new Exception(n);}
 var l=RoadGunnerLevelAuthoring.Current;var original=l.ground.sharedMesh;var originalStats=l.session.spawns.authoredRaiders[0].tuning;const string copy="Assets/RoadGunner/Scenes/LevelEditor_CheckCopy.unity";RoadGunnerLevelAuthoring.SaveAs(l,copy);C("Save As makes private terrain and tuning assets",l.ground.sharedMesh!=original&&l.session.spawns.authoredRaiders[0].tuning!=originalStats);l.session.spawns.authoredRaiders[0].tuning.enemyHealth=90;EditorUtility.SetDirty(l.session.spawns.authoredRaiders[0].tuning);AssetDatabase.SaveAssets();C("Copy override edits preserve source",originalStats.enemyHealth==60);
 Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();RoadGunnerLevelAuthoring.Clear(l);Undo.FlushUndoRecordObjects();Undo.CollapseUndoOperations(group);C("Clear authored content updates pools",l.humanEnemiesRoot.childCount==0&&l.enemyVehiclesRoot.childCount==0&&l.obstaclesRoot.childCount==0&&l.session.spawns.authoredRaiders.Length==0);Undo.PerformUndo();RoadGunnerLevelAuthoring.Wire(l);C("Clear Undo restores content and prefab links",l.humanEnemiesRoot.childCount==4&&l.enemyVehiclesRoot.childCount==2&&l.obstaclesRoot.childCount==3&&PrefabUtility.IsPartOfPrefabInstance(l.humanEnemiesRoot.GetChild(0)));
 var spawn=l.playerSpawn;l.playerSpawn=null;C("Validation reports missing spawn",RoadGunnerLevelAuthoring.Validate(l).Any(v=>v.type==MessageType.Error&&v.text.Contains("spawn")));l.playerSpawn=spawn;
 RoadGunnerLevelAuthoring.Save(l);EditorSceneManager.OpenScene(RoadGunnerLevelEditorChecks.Demo);AssetDatabase.DeleteAsset(copy);AssetDatabase.DeleteAsset("Assets/RoadGunner/Scenes/LevelEditor_CheckCopy_Data");File.WriteAllLines(RoadGunnerLevelEditorChecks.Folder+"/SaveAsChecks.txt",lines);return string.Join("\n",lines);}}
